import re
import json

def parse_json_object(text: str) -> dict | None:
    pattern = r'\{\s*(?:[^{}]*(?:\{[^{}]*\}[^{}]*)*[^{}]*\s*)\}'
    match = re.search(pattern, text)
    if match is not None:
        try:
        d = json.loads(match.group(0.strip()))
        return d
    except json.JSONDecodeError:
        return None
    else:
        return None
